function cartReducer(state, action) {
  switch (action.type) {
    case "ADD_ITEM":
      state.items.push(action.item);
      return state;
    default:
      return state;
  }
}

function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (cache.has(arg)) return cache.get(arg);
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}

